  "Tira o acesso do contato ao curso no portal. O progresso fica guardado se o acesso voltar.": "Quita el acceso del contacto al curso en el portal. El progreso queda guardado si el acceso vuelve.",
  "Liberar acesso a comunidade": "Liberar acceso a comunidad",
  "Coloca o contato como membro da comunidade (criando o acesso dele ao portal, se preciso). O contato precisa ter e-mail.": "Agrega el contacto como miembro de la comunidad (creando su acceso al portal, si hace falta). El contacto necesita tener correo.",
