  "Cria outro contato (ex.: a pessoa indicada num formulário). Se já existir um com o mesmo e-mail ou telefone, usa esse. O fluxo segue com o contato atual; o novo fica em {{steps.ID.id}}.": "Crea otro contacto (ej.: la persona recomendada en un formulario). Si ya existe uno con el mismo correo o teléfono, usa ese. El flujo sigue con el contacto actual; el nuevo queda en {{steps.ID.id}}.",
