  "Ligação do Voice AI terminou": "Llamada del Voice AI terminada",
  "Quando termina uma ligação atendida ou feita pelo Voice AI. Use {{trigger.transcript}} (a conversa inteira), {{trigger.outcome}} (end, transfer, book, timeout) e {{trigger.duration}}: por exemplo, resuma com IA, extraia dados para o contato ou avise a equipe.": "Cuando termina una llamada atendida o hecha por el Voice AI. Usa {{trigger.transcript}} (la conversación completa), {{trigger.outcome}} (end, transfer, book, timeout) y {{trigger.duration}}: por ejemplo, resume con IA, extrae datos para el contacto o avisa al equipo.",
  "Como terminou": "Cómo terminó",
  "De qualquer jeito": "De cualquier forma",
  "Encerrou a conversa": "Cerró la conversación",
  "Transferiu para a equipe": "Transfirió al equipo",
  "Tempo ou silêncio": "Tiempo o silencio",
  "Ligação do Voice AI": "Llamada del Voice AI",
  "Um agente de IA publicado liga para o contato e conversa por voz, com a base de conhecimento dele e o objetivo desta etapa. Pode transferir para a equipe, encerrar ou marcar um horário do serviço escolhido. A transcrição vai para Conversas e dispara Ligação do Voice AI terminou. Usa a OpenAI de quem salvou o fluxo.": "Un agente de IA publicado llama al contacto y conversa por voz, con su base de conocimiento y el objetivo de este paso. Puede transferir al equipo, cerrar o agendar un horario del servicio elegido. La transcripción va a Conversaciones y dispara Llamada del Voice AI terminada. Usa la OpenAI de quien guardó el flujo.",
  "Objetivo da ligação (aceita variáveis)": "Objetivo de la llamada (acepta variables)",
  "Confirme a consulta de {{contact.first_name}} amanhã e ofereça remarcar se precisar.": "Confirma la cita de {{contact.first_name}} mañana y ofrece reprogramar si hace falta.",
  "Primeira fala (vazio: o agente começa sozinho)": "Primera frase (vacío: el agente empieza solo)",
