  "Crie um app em api.slack.com, adicione os escopos chat:write, channels:manage, channels:read, groups:read, users:read.email e instale no workspace. Para os gatilhos, ative Event Subscriptions com a URL abaixo.": "Crea una app en api.slack.com, agrega los permisos chat:write, channels:manage, channels:read, groups:read, users:read.email e instálala en el workspace. Para los disparadores, activa Event Subscriptions con la URL de abajo.",
  "Bot token (xoxb-…)": "Bot token (xoxb-…)",
  "Signing secret (para os gatilhos)": "Signing secret (para los disparadores)",
  "No Google Cloud, crie uma conta de serviço com as APIs Google Sheets e Google Drive ativas, gere a chave JSON e compartilhe cada planilha com o e-mail da conta de serviço. A primeira linha da aba é o cabeçalho.": "En Google Cloud, crea una cuenta de servicio con las API de Google Sheets y Google Drive activas, genera la clave JSON y comparte cada hoja con el correo de la cuenta de servicio. La primera fila de la pestaña es el encabezado.",
  "Chave JSON da conta de serviço": "Clave JSON de la cuenta de servicio",
  "Crie um app personalizado na Shopify com acesso a pedidos e clientes. Em Notificações → Webhooks, crie \"Criação de pedido\" (JSON) apontando para a URL abaixo.": "Crea una app personalizada en Shopify con acceso a pedidos y clientes. En Notificaciones → Webhooks, crea \"Creación de pedido\" (JSON) apuntando a la URL de abajo.",
  "Loja (minhaloja.myshopify.com)": "Tienda (mitienda.myshopify.com)",
  "Token de acesso do app (Admin API)": "Token de acceso de la app (Admin API)",
  "Chave secreta do app (webhooks)": "Clave secreta de la app (webhooks)",
  "Anúncios": "Anuncios",
  "No TikTok Ads Manager (Formulários instantâneos → Integrações → Webhook), cole a URL abaixo.": "En TikTok Ads Manager (Formularios instantáneos → Integraciones → Webhook), pega la URL de abajo.",
  "Envie os leads dos formulários do LinkedIn para a URL abaixo (Lead Sync por webhook ou um integrador como o Make).": "Envía los leads de los formularios de LinkedIn a la URL de abajo (Lead Sync por webhook o un integrador como Make).",
  "Em airtable.com/create/tokens, crie um token com data.records:read e data.records:write e acesso às bases.": "En airtable.com/create/tokens, crea un token con data.records:read y data.records:write y acceso a las bases.",
  "Token pessoal (pat…)": "Token personal (pat…)",
  "Em Configurações → Integrações → Apps privados, crie um app com crm.objects.contacts e crm.objects.deals (leitura e escrita).": "En Configuración → Integraciones → Apps privadas, crea una app con crm.objects.contacts y crm.objects.deals (lectura y escritura).",
  "Token do app privado": "Token de la app privada",
  "Crie uma integração interna em notion.so/my-integrations e conecte o banco de dados a ela (… → Conexões).": "Crea una integración interna en notion.so/my-integrations y conecta la base de datos a ella (… → Conexiones).",
  "Token da integração (secret_… ou ntn_…)": "Token de la integración (secret_… o ntn_…)",
  "Projetos": "Proyectos",
  "Em Asana → Console de desenvolvedor, crie um token de acesso pessoal.": "En Asana → Consola de desarrollador, crea un token de acceso personal.",
  "Token de acesso pessoal": "Token de acceso personal",
  "Em ClickUp → Configurações → Apps, gere o token pessoal.": "En ClickUp → Configuración → Apps, genera el token personal.",
