  "Chave de assinatura do webhook (opcional)": "Clave de firma del webhook (opcional)",
  "Em Cal.com → Configurações → Desenvolvedor → Webhooks, crie um webhook com a URL abaixo.": "En Cal.com → Configuración → Desarrollador → Webhooks, crea un webhook con la URL de abajo.",
  "Segredo do webhook (opcional)": "Secreto del webhook (opcional)",
  "No formulário → Connect → Webhooks, adicione a URL abaixo (e o segredo, se quiser assinatura).": "En el formulario → Connect → Webhooks, agrega la URL de abajo (y el secreto, si quieres firma).",
  "No formulário → Configurações → Integrações → WebHooks, cole a URL abaixo.": "En el formulario → Configuración → Integraciones → WebHooks, pega la URL de abajo.",
  "No formulário, abra Extensões → Apps Script e cole o script mostrado depois de conectar: cada resposta vai para a URL abaixo.": "En el formulario, abre Extensiones → Apps Script y pega el script que aparece después de conectar: cada respuesta va a la URL de abajo.",
